-- PocaPop Vault: snapshot MKPC data, replace the catalog, and retain staff/reference data.
select pg_advisory_xact_lock(725193);
lock table public.cards, public.card_idols, public.packs, public.rarities, public.groups, public.idols, public.group_memberships, public.import_history in access exclusive mode;
create schema if not exists vault_archive;
revoke all on schema vault_archive from public, anon, authenticated;
create table if not exists vault_archive.catalog_snapshots (
  name text primary key, archived_at timestamptz not null default now(), payload jsonb not null
);
revoke all on all tables in schema vault_archive from public, anon, authenticated;
do $backup$
declare tab text; snapshot jsonb := '{}'::jsonb; rows jsonb;
begin
  foreach tab in array array['cards','card_idols','packs','rarities','groups','idols','group_memberships','import_history','settings','group_kpopping_links','idol_kpopping_links','idol_planner_profiles'] loop
    if to_regclass('public.'||tab) is not null then
      execute format('select coalesce(jsonb_agg(to_jsonb(t)),''[]''::jsonb) from public.%I t',tab) into rows;
      snapshot := snapshot || jsonb_build_object(tab,rows);
    end if;
  end loop;
  insert into vault_archive.catalog_snapshots(name,payload) values('mkpc_before_pocapop_20260930',snapshot);
end $backup$;

delete from public.card_idols;
delete from public.cards;
delete from public.packs;
delete from public.group_memberships;
delete from public.idols;
delete from public.groups;
delete from public.import_history;
delete from public.rarities;

alter table public.groups add column game_group_id text unique;
alter table public.idols add column game_idol_id text unique;
alter table public.packs add column game_pack_id text unique;
alter table public.packs add column catalog_status text not null default 'Draft' check(catalog_status in ('Draft','Ready','Disabled'));
alter table public.packs add column catalog_size integer check(catalog_size >= 0);
alter table public.packs add column exclusive boolean not null default false;
alter table public.rarities alter column numeric_value drop not null;
alter table public.rarities add column game_key text unique check(game_key in ('Common','Uncommon','Rare','Epic','Legendary','Mythic'));
alter table public.cards add column game_card_id text unique;
alter table public.cards add column image_asset_id text check(image_asset_id is null or image_asset_id ~ '^[0-9]{1,16}$');
alter table public.cards add column catalog_status text not null default 'Draft' check(catalog_status in ('Draft','Ready','Disabled'));
alter table public.cards add column premium_tier text check(premium_tier in ('Petal','Silk','Royal','Crown'));
create table public.pack_rarities (
  pack_id uuid not null references public.packs on delete cascade,
  rarity_id uuid not null references public.rarities on delete restrict,
  display_name text not null,
  card_count integer not null check(card_count>0),
  female_count integer not null check(female_count>=0),
  male_count integer not null check(male_count>=0),
  weight bigint not null check(weight>=0),
  total_weight bigint not null check(total_weight>0 and weight<=total_weight),
  primary key(pack_id,rarity_id),
  check(female_count+male_count=card_count)
);
alter table public.pack_rarities enable row level security;
create policy staff_access on public.pack_rarities for all to authenticated using(public.is_staff()) with check(public.is_staff());
grant select,insert,update,delete on public.pack_rarities to authenticated;
revoke all on public.pack_rarities from anon;
insert into public.rarities(label,game_key,sort_order,numeric_value)
select key,key,ordinality-1,null from unnest(array['Common','Uncommon','Rare','Epic','Legendary','Mythic']) with ordinality as tier(key,ordinality);

create or replace function public.save_card(payload jsonb) returns uuid language plpgsql security invoker set search_path=public as $card$
declare cid uuid; ids uuid[]; pid uuid; rid uuid; slot_value text;
begin
  if not is_staff() then raise exception 'Moderator access required';end if;
  perform pg_advisory_xact_lock(725193);
  cid=coalesce(nullif(payload->>'id','')::uuid,gen_random_uuid());
  pid=(payload->>'pack_id')::uuid;rid=(payload->>'rarity_id')::uuid;slot_value=nullif(payload->>'slot','');
  select coalesce(array_agg(distinct value::uuid order by value::uuid),'{}'::uuid[]) into ids from jsonb_array_elements_text(coalesce(payload->'idol_ids','[]'));
  if cardinality(ids)=0 and nullif(payload->>'group_id','') is null then raise exception 'Choose an idol or group';end if;
  if exists(select 1 from pack_rarities where pack_id=pid) and not exists(select 1 from pack_rarities where pack_id=pid and rarity_id=rid) then raise exception 'This rarity is not configured for this pack';end if;
  if exists(select 1 from cards c where c.id<>cid and c.pack_id=pid and c.rarity_id=rid and norm(c.slot)=norm(slot_value) and c.group_id is not distinct from nullif(payload->>'group_id','')::uuid and coalesce((select array_agg(ci.idol_id order by ci.idol_id) from card_idols ci where ci.card_id=c.id),'{}'::uuid[])=ids) then raise exception 'An exact duplicate card already exists';end if;
  insert into cards(id,pack_id,rarity_id,slot,card_name,group_id,pic_status,source_url,notes,game_card_id,image_asset_id,catalog_status,premium_tier)
  values(cid,pid,rid,slot_value,nullif(payload->>'card_name',''),nullif(payload->>'group_id','')::uuid,nullif(payload->>'pic_status',''),nullif(payload->>'source_url',''),nullif(payload->>'notes',''),nullif(payload->>'game_card_id',''),nullif(payload->>'image_asset_id',''),coalesce(nullif(payload->>'catalog_status',''),'Draft'),nullif(payload->>'premium_tier',''))
  on conflict(id) do update set pack_id=excluded.pack_id,rarity_id=excluded.rarity_id,slot=excluded.slot,card_name=excluded.card_name,group_id=excluded.group_id,pic_status=excluded.pic_status,source_url=excluded.source_url,notes=excluded.notes,
    game_card_id=case when payload ? 'game_card_id' then excluded.game_card_id else cards.game_card_id end,
    image_asset_id=case when payload ? 'image_asset_id' then excluded.image_asset_id else cards.image_asset_id end,
    catalog_status=case when payload ? 'catalog_status' then excluded.catalog_status else cards.catalog_status end,
    premium_tier=case when payload ? 'premium_tier' then excluded.premium_tier else cards.premium_tier end;
  delete from card_idols where card_id=cid;
  insert into card_idols(card_id,idol_id) select cid,unnest(ids);
  return cid;
end $card$;

create or replace function public.commit_import(payload jsonb) returns jsonb language plpgsql security invoker set search_path=public as $import$
declare r jsonb; gid uuid; iid uuid; pid uuid; rid uuid; made integer=0; skipped integer=0; mode text; gname text; selected uuid[];
begin
  if not is_staff() then raise exception 'Moderator access required';end if;
  perform pg_advisory_xact_lock(725193);
  mode=payload->>'mode';
  if mode not in ('cards','roster') or jsonb_array_length(payload->'rows')>10000 then raise exception 'Invalid import';end if;
  if mode='roster' then
    for gname in select distinct value->>'group' from jsonb_array_elements(payload->'rows') loop
      if norm(gname)='' then raise exception 'Group is required';end if;
      selected='{}';
      for r in select value from jsonb_array_elements(payload->'rows') where norm(value->>'group')=norm(gname) loop
        iid=resolve_artist(r->>'idol',gname,r->>'gender');
        select id into gid from groups where normalized_name=norm(gname);
        update group_memberships set membership_status=coalesce(nullif(r->>'membership_status',''),'current') where group_id=gid and idol_id=iid;
        selected=array_append(selected,iid);made=made+1;
      end loop;
      update group_memberships set membership_status='former' where group_id=gid and not(idol_id=any(selected));
      if not exists(select 1 from group_memberships where group_id=gid and membership_status='current') then raise exception 'A configured roster needs at least one current member';end if;
      update groups set roster_configured=true where id=gid;
    end loop;
  else
    for r in select value from jsonb_array_elements(payload->'rows') loop
      iid=resolve_artist(r->>'idol',r->>'group',r->>'gender');
      gid=null;select id into gid from groups where normalized_name=norm(r->>'group');
      insert into packs(name,pack_type,pack_number) values(r->>'sheet',coalesce(nullif(regexp_replace(r->>'sheet','\s+[0-9]+$',''),''),r->>'sheet'),substring(r->>'sheet' from '\s+([0-9]+)$')::integer) on conflict(normalized_name) do nothing;
      select id into pid from packs where normalized_name=norm(r->>'sheet');
      rid=null;
      select id into rid from rarities where id=nullif(r->>'rarityId','')::uuid and active;
      if rid is null then select id into rid from rarities where numeric_value=nullif(r->>'rarityValue','')::numeric and active;end if;
      if rid is null then raise exception 'Unknown or inactive rarity';end if;
      if exists(select 1 from cards c where c.pack_id=pid and c.rarity_id=rid and norm(c.slot)=norm(r->>'slot') and (select count(*) from card_idols ci where ci.card_id=c.id)=1 and exists(select 1 from card_idols ci where ci.card_id=c.id and ci.idol_id=iid)) then skipped=skipped+1;continue;end if;
      perform save_card(jsonb_build_object('pack_id',pid,'rarity_id',rid,'slot',r->>'slot','group_id',gid,'pic_status',r->>'pic_status','source_url',r->>'source_url','notes',r->>'notes','idol_ids',jsonb_build_array(iid)));
      made=made+1;
    end loop;
  end if;
  insert into import_history(filename,rows_processed,rows_created,rows_skipped,warnings) values(left(payload->>'filename',255),coalesce((payload->>'processed')::integer,jsonb_array_length(payload->'rows')),made,skipped+coalesce((payload->>'skipped')::integer,0),coalesce(payload->'warnings','[]'));
  return jsonb_build_object('created',made,'skipped',skipped);
end $import$;

create function public.save_pocapop_draft(payload jsonb) returns uuid language plpgsql security invoker set search_path=public as $draft$
declare pid uuid; tier jsonb; row_data jsonb; iid uuid; gid uuid; rid uuid; counts integer[]; weights bigint[]; i integer; key text; premium boolean; seen uuid[] := '{}';
begin
  if not is_staff() then raise exception 'Moderator access required';end if;
  perform pg_advisory_xact_lock(725193);
  if payload->>'pack_type' not in ('Rebirth','Premium') then raise exception 'Unsupported pack type';end if;
  premium := payload->>'pack_type'='Premium';
  counts := case when premium then array[0,0,10,8,4,2] else array[18,12,8,6,2,2] end;
  weights := case when premium then array[0,0,7000000,2580000,400000,20000]::bigint[] else array[7000000,2000000,700000,240000,56000,4000]::bigint[] end;
  if jsonb_typeof(payload->'rows') is distinct from 'array' or jsonb_array_length(payload->'rows') <> (case when premium then 24 else 48 end) then raise exception 'Pack size does not match PocaPop layout';end if;
  if trim(coalesce(payload->>'game_pack_id','')) !~ '^(RB|HB)[0-9]{2,}$' then raise exception 'Choose a valid RB or HB PackID';end if;
  if (premium and payload->>'game_pack_id' !~ '^HB') or (not premium and payload->>'game_pack_id' !~ '^RB') then raise exception 'PackID prefix does not match pack type';end if;
  insert into packs(name,game_pack_id,pack_type,pack_number,catalog_size,status,catalog_status)
    values(payload->>'name',payload->>'game_pack_id',payload->>'pack_type',case when premium then null else substring(payload->>'game_pack_id' from 3)::integer end,case when premium then 24 else 48 end,'draft','Draft') returning id into pid;
  for i in 1..6 loop
    key := (array['Common','Uncommon','Rare','Epic','Legendary','Mythic'])[i];
    if counts[i]=0 then continue;end if;
    select id into rid from rarities where game_key=key and active;
    if rid is null then raise exception 'Missing active tier %',key;end if;
    if (select count(*) from jsonb_array_elements(payload->'rows') x where x->>'rarity_id'=rid::text)<>counts[i] then raise exception 'Incorrect card count for %',key;end if;
    if (select count(*) from jsonb_array_elements(payload->'rows') x join idols a on a.id=(x->>'idol_id')::uuid where x->>'rarity_id'=rid::text and a.gender='female')<>counts[i]/2 or
       (select count(*) from jsonb_array_elements(payload->'rows') x join idols a on a.id=(x->>'idol_id')::uuid where x->>'rarity_id'=rid::text and a.gender='male')<>counts[i]/2 then raise exception 'Each rarity requires equal female and male cards';end if;
    insert into pack_rarities values(pid,rid,case when premium then (array['','','Petal','Silk','Royal','Crown'])[i] else key end,counts[i],counts[i]/2,counts[i]/2,weights[i],10000000);
  end loop;
  for row_data in select value from jsonb_array_elements(payload->'rows') loop
    iid := (row_data->>'idol_id')::uuid;
    if iid=any(seen) then raise exception 'An idol may appear only once per planned pack';end if;
    seen := array_append(seen,iid);
    select group_id into gid from group_memberships where idol_id=iid and membership_status='current' order by id limit 1;
    perform save_card(jsonb_build_object('pack_id',pid,'rarity_id',row_data->>'rarity_id','slot',row_data->>'slot','group_id',gid,'pic_status','To Find','idol_ids',jsonb_build_array(iid)));
  end loop;
  return pid;
end $draft$;
revoke all on function public.save_pocapop_draft(jsonb) from public,anon;
grant execute on function public.save_pocapop_draft(jsonb) to authenticated;

-- The old generator encodes MKPC percentages. Retire its write/generation entry points.
do $retire$ declare proc record;
begin
  for proc in select p.oid::regprocedure signature from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in ('save_pack_planner_draft','pack_planner_full_pack','pack_planner_pool','pack_planner_candidates','pack_planner_reroll_candidate','pack_planner_search_candidates') loop
    execute format('revoke execute on function %s from public,anon,authenticated',proc.signature);
  end loop;
end $retire$;

