kID":"RB07","slot":"358"},{"CatalogStatus":"Ready","ImageAssetId":90594301217756,"Rarity":"Common","IdolID":"IDOL-FLARE-U-CHUEI-LIYU","CardID":"RB07-FLARE-U-CHUEI-LIYU-001","PackID":"RB07","slot":"359"},{"CatalogStatus":"Ready","ImageAssetId":138686470746102,"Rarity":"Common","IdolID":"IDOL-ONEWE-YONGHOON","CardID":"RB07-ONEWE-YONGHOON-001","PackID":"RB07","slot":"360"},{"CatalogStatus":"Ready","ImageAssetId":124980252397491,"Rarity":"Mythic","IdolID":"IDOL-SOLO-IU","CardID":"EX01-SOLO-IU-001","PackID":"EX01","slot":"361"},{"CatalogStatus":"Ready","ImageAssetId":112827405802552,"Rarity":"Mythic","IdolID":"IDOL-RESCENE-GROUP","CardID":"EX02-RESCENE-GROUP-001","PackID":"EX02","slot":"362"}]}'::jsonb; r jsonb; t jsonb; pid uuid; iid uuid; gid uuid; rid uuid; cid uuid;
begin
  for r in select value from jsonb_array_elements(data->'groups') loop
    insert into public.groups(name,game_group_id) values(r->>'name',r->>'game_group_id');
  end loop;
  for r in select value from jsonb_array_elements(data->'idols') loop
    insert into public.idols(stage_name,gender,game_idol_id) values(r->>'name',r->>'gender',r->>'game_idol_id') returning id into iid;
    select id into gid from public.groups where game_group_id=r->>'game_group_id';
    if gid is not null and r->>'game_group_id'<>'GROUP-SOLO' then insert into public.group_memberships(group_id,idol_id) values(gid,iid);end if;
  end loop;
  for r in select value from jsonb_array_elements(data->'packs') loop
    insert into public.packs(name,game_pack_id,pack_type,pack_number,catalog_status,catalog_size,exclusive,status,notes)
      values(r->>'name',r->>'game_pack_id',r->>'pack_type',(r->>'pack_number')::integer,r->>'catalog_status',(r->>'catalog_size')::integer,(r->>'exclusive')::boolean,'ready','Imported from PocaPop! DEV PlaceVersion 332. Release status awaits moderator verification.') returning id into pid;
    for t in select value from jsonb_array_elements(r->'tiers') loop
      select id into rid from public.rarities where game_key=t->>'key';
      insert into public.pack_rarities values(pid,rid,t->>'display_name',(t->>'card_count')::integer,(t->>'female_count')::integer,(t->>'male_count')::integer,(t->>'weight')::bigint,(t->>'total_weight')::bigint);
    end loop;
  end loop;
  for r in select value from jsonb_array_elements(data->'cards') loop
    select id into pid from public.packs where game_pack_id=r->>'PackID';
    select id into iid from public.idols where game_idol_id=r->>'IdolID';
    select g.id into gid from public.groups g where g.game_group_id=(select a->>'game_group_id' from jsonb_array_elements(data->'idols') a where a->>'game_idol_id'=r->>'IdolID');
    select id into rid from public.rarities where game_key=r->>'Rarity';
    insert into public.cards(pack_id,rarity_id,group_id,slot,game_card_id,image_asset_id,catalog_status,premium_tier,pic_status)
      values(pid,rid,gid,r->>'slot',r->>'CardID',r->>'ImageAssetId',r->>'CatalogStatus',r->>'PremiumTier','Selected') returning id into cid;
    insert into public.card_idols values(cid,iid);
  end loop;
  update public.settings set include_unreleased=true;
end $seed$;
-- Reuse curated reference matches only when the artist/group identity still matches.
do $links$
begin
  if to_regclass('public.group_kpopping_links') is not null then
    insert into public.group_kpopping_links(group_id,kpopping_group_id,match_method,confirmed)
    select g.id,l->>'kpopping_group_id',l->>'match_method',(l->>'confirmed')::boolean
    from vault_archive.catalog_snapshots s
    cross join lateral jsonb_array_elements(s.payload->'group_kpopping_links') l
    join lateral jsonb_array_elements(s.payload->'groups') oldg on oldg->>'id'=l->>'group_id'
    join public.groups g on g.normalized_name=public.norm(oldg->>'name')
    where s.name='mkpc_before_pocapop_20260930'
    on conflict do nothing;
  end if;
  if to_regclass('public.idol_kpopping_links') is not null then
    with candidates as (
      select distinct i.id,l->>'kpopping_artist_id' as reference_id,l->>'match_method' as method,(l->>'confirmed')::boolean as confirmed
      from vault_archive.catalog_snapshots s
      cross join lateral jsonb_array_elements(s.payload->'idol_kpopping_links') l
      join lateral jsonb_array_elements(s.payload->'idols') oldi on oldi->>'id'=l->>'idol_id'
      join public.idols i on i.normalized_name=public.norm(oldi->>'stage_name')
      where s.name='mkpc_before_pocapop_20260930' and (
        exists (
          select 1 from jsonb_array_elements(s.payload->'group_memberships') oldm
          join lateral jsonb_array_elements(s.payload->'groups') oldg on oldg->>'id'=oldm->>'group_id'
          join public.groups g on g.normalized_name=public.norm(oldg->>'name')
          join public.group_memberships gm on gm.group_id=g.id and gm.idol_id=i.id
          where oldm->>'idol_id'=oldi->>'id'
        ) or (
          not exists(select 1 from public.group_memberships gm where gm.idol_id=i.id) and
          not exists(select 1 from jsonb_array_elements(s.payload->'group_memberships') oldm where oldm->>'idol_id'=oldi->>'id')
        )
      )
    ), unique_candidates as (
      select id,min(reference_id) as reference_id,min(method) as method,bool_and(confirmed) as confirmed
      from candidates group by id having count(distinct reference_id)=1
    )
    insert into public.idol_kpopping_links(idol_id,kpopping_artist_id,match_method,confirmed)
    select id,reference_id,method,confirmed from unique_candidates on conflict do nothing;
  end if;
end $links$;
